_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_kernel")

class ModelNew(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B) with a large K dimension,
    implemented via a custom PTX kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32, "Only float32 supported"

        M, K = A.shape
        K2, N = B.shape
        assert K == K2, "Inner dimensions must match"

        splits = 1
        max_splits = 64
        while splits < max_splits and K % (splits * 2) == 0:
            splits *= 2
        C = torch.zeros((M, N), device=A.device, dtype=A.dtype)

        module = _get_ptx_module()

        block = (16, 16, 1)
        N_TILE = 64  # each thread computes 4 output columns (matches kernel's 64-wide N-tile: 16 threads * 4 cols/thread)
        grid = ((N + N_TILE - 1) // N_TILE, (M + block[1] - 1) // block[1], splits)

        module.launch(
            "matmul_kernel",
            grid=grid,
            block=block,
            arguments=[A, B, C, i32(M), i32(N), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C
        N_TILE = 64  # each thread computes 4 output columns (register/thread-level tiling)

